#include <bits/stdc++.h>
using namespace std;

double d2(double ax, double ay, double bx, double by) {
    return (bx - ax) * (bx - ax) + (by - ay) * (by - ay);
}

vector<double> crossSimple(long x, long y, long r, long tx, long ty, long tr) {
    double d2Val = d2(x, y, tx, ty);
    double r_sq = r * r;
    double tr_sq = tr * tr;
    if (d2Val < (r - tr) * (r - tr) || d2Val > (r + tr) * (r + tr))
        return {};
    double base = atan2(ty - y, tx - x);
    double cosVal = (d2Val + r_sq - tr_sq) / (2.0 * sqrt(d2Val) * r);
    if (cosVal > 1.0) cosVal = 1.0;
    if (cosVal < -1.0) cosVal = -1.0;
    double wing = acos(cosVal);
    return {base - wing, base + wing};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<array<long,3>> circles(n);
    for (int i = 0; i < n; i++) {
        cin >> circles[i][0] >> circles[i][1] >> circles[i][2];
    }
    vector<double> pts;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            vector<double> angles = crossSimple(circles[i][0], circles[i][1], circles[i][2], circles[j][0], circles[j][1], circles[j][2]);
            for (double a : angles) {
                pts.push_back(circles[i][0] + circles[i][2] * cos(a));
                pts.push_back(circles[i][1] + circles[i][2] * sin(a));
            }
        }
    }
    int count = pts.size() / 2;
    vector<bool> removeFlag(count, false);
    for (int i = 0; i < count; i++) {
        for (int j = i + 1; j < count; j++) {
            double dx = pts[2*i] - pts[2*j];
            double dy = pts[2*i + 1] - pts[2*j + 1];
            if (d2(pts[2*i], pts[2*i + 1], pts[2*j], pts[2*j + 1]) < 1e-12) {
                removeFlag[j] = true;
            }
        }
    }
    vector<double> uniquePts;
    for (int i = 0; i < count; i++) {
        if (!removeFlag[i]) {
            uniquePts.push_back(pts[2*i]);
            uniquePts.push_back(pts[2*i + 1]);
        }
    }
    int totalPts = uniquePts.size() / 2;
    int totalEdges = 0;
    int components = 1;
    for (int i = 0; i < n; i++) {
        int eCount = 0;
        for (int k = 0; k < totalPts; k++) {
            double px = uniquePts[2*k];
            double py = uniquePts[2*k + 1];
            double dist = d2(px, py, circles[i][0], circles[i][1]);
            if (fabs(dist - circles[i][2] * circles[i][2]) < 1e-12) {
                eCount++;
            }
        }
        if (eCount == 0) components++;
        totalEdges += eCount;
    }
    if (components > n) components = n;
    cout << totalEdges - totalPts + components + 1 << "\n";
    return 0;
}

